dt = time_ns() - t0

vf = Array(b.v)
sx = std(vf[:, 1]); sy = std(vf[:, 3])
ex = emit_geom(vf[:, 1], vf[:, 2]); ey = emit_geom(vf[:, 3], vf[:, 4])
println("Track: ", dt, "ns")
println("Validate: {\"sigma_x\": ", sx, ", \"sigma_y\": ", sy,
        ", \"emit_x\": ", ex, ", \"emit_y\": ", ey, "}")
